class Base {
public:
  virtual void func() = 0; 
  virtual ~Base() {} // Virtual destructor is crucial
};

class Derived : public Base {
public:
  void func() override {}
  ~Derived() override {}
};

int main() {
  Base* b = new Derived();
  delete b; // Correctly calls Derived::~Derived() due to virtual destructor
  return 0;
}

code_example:
#include <iostream>
#include <memory>
class Base {
public:
  virtual void func() = 0;
  virtual ~Base() {} // Virtual destructor
};

class Derived : public Base {
public:
  void func() override { std::cout << "Derived func called" << std::endl; }
  ~Derived() override { std::cout << "Derived destructor called" << std::endl; }
};

int main() {
  std::unique_ptr<Base> b(new Derived());
  b->func();
  //delete b; //Managed by unique_ptr
  return 0;
}
